"""
	For chunks of fps number of frames for actual as well as predicted viewports
	"""
def get_chunks(
    act_viewport: Any, pred_viewport: Any, frame_nos: Any, max_frame: Any, fps: Any
) -> object {
    (act_tiles, pred_tiles, chunk_frames) = ([], [], []);
    chunk_size = fps;
    number_of_chunks = int((len(act_viewport) / chunk_size));
    for i in range(number_of_chunks) {
        act_tiles.append(act_viewport[(i * chunk_size):((i + 1) * chunk_size)]);
        pred_tiles.append(pred_viewport[(i * chunk_size):((i + 1) * chunk_size)]);
        chunk_frames.append(frame_nos[(i * chunk_size):((i + 1) * chunk_size)]);
    }
    act_tiles.append(act_viewport[(number_of_chunks * chunk_size):]);
    pred_tiles.append(pred_viewport[(number_of_chunks * chunk_size):]);
    chunk_frames.append(frame_nos[(number_of_chunks * chunk_size):]);
    return (act_tiles, pred_tiles, chunk_frames);
}

"""
	brief: computes ten average of the list
	args:
		tab: a list of numeric value expects at leas one positive value
	return:
		the computed average
	raises:
		ValueError if expected a list as input
		ValueError if no positive value found
	"""
def average_above_zero(tab: Any) -> object {
    if not isinstance(tab, `list) {
        raise ValueError('Expected a list as input');
    }
    valSum = 0.0;
    nPositiveValues = 0;
    for i in range(len(tab)) {
        if (tab[i] > 0) {
            valSum += float(tab[i]);
            nPositiveValues += 1;
        }
    }
    if (nPositiveValues <= 0) {
        raise ValueError('No positive value found');
    }
    avg = valSum / nPositiveValues;
    return avg;
}

"""
    Returns True if the two strings are equal, False otherwise.

    The time taken is independent of the number of characters that match.

    For the sake of simplicity, this function executes in constant time only
    when the two strings have the same length. It short-circuits when they
    have different lengths.
    """
def constant_time_compare(val1: Any, val2: Any) -> object {
    if (len(val1) != len(val2)) {
        return False;
    }
    result = 0;
    for (x, y) in zip(val1, val2) {
        result |= x ^ y;
    }
    return (result == 0);
}

"""Checks if string composer-X.Y.Z-airflow-A.B.C is Composer v1 version."""
def IsImageVersionStringComposerV1(image_version: Any) -> object {
    return (
        not image_version
        or image_version.startswith('composer-1.')
        or image_version.startswith('composer-latest')
    );
}

"""
    Get all unique patterns in the repository.

    Keyword arguments:
    repo -- object containing properties of the repo
    """
def get_patterns_per_repository(repo: Any) -> object {
    dynamic_count = 0;
    if ('DYNAMIC-PATTERN' in repo['uniquePatterns']) {
        dynamic_count += repo['uniquePatterns']['DYNAMIC-PATTERN'];
    }
    return (len(repo['uniquePatterns']) + dynamic_count);
}

"""
    Replaces (MySQL) instances like 'CONCAT(A, B)' with 'CONCAT_WS(MID(CHAR(0), 0, 0), A, B)' counterpart

    Requirement:
        * MySQL

    Tested against:
        * MySQL 5.0

    Notes:
        * Useful to bypass very weak and bespoke web application firewalls
          that filter the CONCAT() function

    >>> tamper('CONCAT(1,2)')
    'CONCAT_WS(MID(CHAR(0),0,0),1,2)'
    """
def tamper(payload: Any, **kwargs: Any) -> object {
    if payload {
        payload = payload.replace("CONCAT(", "CONCAT_WS(MID(CHAR(0),0,0),");
    }
    return payload;
}
